    static void EarnRound(GameState a,GameState b,int expectedWins) {
            a.ArenaState=b.ArenaState=Qualifier.Fight;a.ArenaStatistic.AcceptBox=b.ArenaStatistic.AcceptBox=true;
            var prior=new Qualifier.QualifierList.QualifierGroup(a,b);
            var retention=Activator.CreateInstance(Feature("ArenaDisconnectRetention"),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{4,null},null);
            Console.WriteLine("[arena-process] admission round="+expectedWins+" a-dead="+a.Entity.Dead+" b-dead="+b.Entity.Dead+" a-action="+a.Action+" b-action="+b.Action
                +" a-owner="+(typeof(GameState).GetField("ArenaShutdownRetention",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(a)!=null)
                +" b-owner="+(typeof(GameState).GetField("ArenaShutdownRetention",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(b)!=null));
            Call(typeof(Qualifier),"ImportMatched",prior,retention);Require(a.QualifierGroup==prior && b.QualifierGroup==prior);
            Console.WriteLine("[arena-process] imported a-map="+a.Entity.MapID+" b-map="+b.Entity.MapID+" recorded="+prior.GetType().GetField("ParticipationRecorded",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(prior)+" interrupted="+prior.GetType().GetField("AdmissionInterrupted",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(prior));
            prior.End(b);var limit=DateTime.UtcNow.AddSeconds(10);
            do {
                retention.GetType().GetMethod("Tick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(retention,new object[]{16});
                if(a.QualifierGroup==null && b.QualifierGroup==null
                    && typeof(GameState).GetField("ArenaShutdownRetention",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(a)==null
                    && typeof(GameState).GetField("ArenaShutdownRetention",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(b)==null)break;
                System.Threading.Thread.Sleep(50);
            }while(DateTime.UtcNow<limit);
            Console.WriteLine("[arena-process] earned-round="+expectedWins+" wins="+a.ArenaStatistic.TodayWin);
            Require(a.QualifierGroup==null && b.QualifierGroup==null && a.ArenaStatistic.TodayWin==expectedWins);
    }
    static void Capture() {
        Require((long)Sql("SELECT count(*) FROM entities WHERE uid BETWEEN 4294903001 AND 4294903005")==0);
        Sql("CREATE TABLE revora_arena_process_probe(solo uuid NOT NULL,team uuid NOT NULL,fingerprint text)");
        var town=Kernel.Maps[1002];var a=Player(town);var b=Player(town);var c=Player(town);var d=Player(town);var e=Player(town);
        // Earn eight results through registered matches; the ninth remains pending across restart.
        for(int round=0;round<8;round++) {
            EarnRound(a,b,round+1);
        }
        Require((long)Sql("SELECT count(*) FROM revora_arena_daily_rewards WHERE uid=@uid","uid",(long)FirstUid)==0);
        a.ArenaState=b.ArenaState=Qualifier.Fight;a.ArenaStatistic.AcceptBox=b.ArenaStatistic.AcceptBox=true;
        c.Team=new Revora.Game.ConquerStructures.Team(c);c.Team.Add(e);d.Team=new Revora.Game.ConquerStructures.Team(d);
        var solo=new Qualifier.QualifierList.QualifierGroup(a,b);
        var team=new TeamQualifier.QualifierList.QualifierGroup(c,d);
        var instance=BindingFlags.Instance|BindingFlags.NonPublic;
        var soloOwner=Activator.CreateInstance(Feature("ArenaDisconnectRetention"),instance,null,new object[]{4,null},null);
        var teamOwner=Activator.CreateInstance(Feature("TeamArenaDisconnectRetention"),instance,null,new object[]{4,null},null);
        Call(typeof(Qualifier),"ImportMatched",solo,soloOwner);Call(typeof(TeamQualifier),"ImportMatched",team,teamOwner);
        Require(a.QualifierGroup==solo && b.QualifierGroup==solo && c.TeamQualifierGroup==team && d.TeamQualifierGroup==team && e.TeamQualifierGroup==team);
        var soloId=(Guid)solo.GetType().GetField("ParticipationKey",instance).GetValue(solo);
        var teamId=(Guid)team.GetType().GetField("ResultKey",instance).GetValue(team);
        Sql(@"INSERT INTO revora_arena_process_probe(solo,team) VALUES(@solo,@team);
CREATE FUNCTION revora_arena_probe_suppress() RETURNS trigger LANGUAGE plpgsql AS 'BEGIN RETURN NULL; END';
CREATE TRIGGER revora_arena_probe_suppress BEFORE INSERT ON revora_arena_result_statistics FOR EACH ROW EXECUTE FUNCTION revora_arena_probe_suppress();
CREATE TRIGGER revora_arena_probe_suppress BEFORE INSERT ON revora_team_arena_results FOR EACH ROW EXECUTE FUNCTION revora_arena_probe_suppress();", "solo",soloId,"team",teamId);
        solo.End(b);team.End(d);
        Call(Feature("ArenaResultCoordinator"),"Complete",solo);Call(Feature("TeamArenaResultCoordinator"),"Complete",team);
        Require((bool)Sql(@"SELECT EXISTS(SELECT 1 FROM revora_arena_result_intents WHERE run=@solo)
AND EXISTS(SELECT 1 FROM revora_team_arena_intents WHERE id=@team)
AND NOT EXISTS(SELECT 1 FROM revora_arena_result_commits WHERE run=@solo)
AND NOT EXISTS(SELECT 1 FROM revora_team_arena_results WHERE id=@team)","solo",soloId,"team",teamId));
        // Must return pending rather than exiting while the retained writes are suppressed.
        Server.CommandsAI("@close");
        Require(a.QualifierGroup==solo && c.TeamQualifierGroup==team && Kernel.GamePool.ContainsKey(a.Entity.UID));
        Console.WriteLine("[arena-process] pending-close-preserved-both-results");
        // Deliberate process interruption; restart must recover the saved causal intents.
        Environment.Exit(0);
    }
