        }
        Require((long)Sql("SELECT count(*) FROM revora_arena_result_statistics WHERE uid=@uid AND won","uid",(long)FirstUid)==9);
        Require((long)Sql("SELECT count(*) FROM revora_arena_daily_rewards WHERE uid=@uid AND milestone='wins9' AND honor=500 AND item_type=723700 AND rune_type=4030101","uid",(long)FirstUid)==1);
        nextUid=FirstUid;var winner=Player(Kernel.Maps[1002],true);
        Call(Feature("ArenaRewardDelivery"),"Tick",winner);Call(Feature("ArenaDailyRewards"),"Pay",winner);
        Require(!(bool)typeof(Entity).GetField("PersistenceRequiresReload",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(winner.Entity) && winner.CurrentHonor==500 && winner.HistoryHonor==500);
        Require((bool)Sql(@"SELECT count(*)=1 FROM revora_arena_daily_rewards r
JOIN items i ON i.uid=r.item_uid AND i.entityid=r.uid AND i.id=723700
JOIN items g ON g.uid=r.rune_uid AND g.entityid=r.uid AND g.id=4030101 AND g.bound=1
WHERE r.uid=@uid AND r.milestone='wins9' AND r.paid_at IS NOT NULL","uid",(long)FirstUid));
        Require((long)Sql("SELECT count(*) FROM items WHERE entityid=@uid","uid",(long)FirstUid)==2);
        Require(Convert.ToInt64(Sql("SELECT currenthonor FROM arena WHERE entityid=@uid","uid",(long)FirstUid))==500
            && Convert.ToInt64(Sql("SELECT currenthonor FROM teamarena WHERE entityid=@uid","uid",(long)FirstUid))==500);
        Console.WriteLine("[arena-process] nine-earned-wins-reward-loaded-once");
        var fingerprint=(string)Sql(@"SELECT md5(string_agg(a.entityid::text||':'||a.arenapoints::text||':'||a.todaywin::text||':'||a.todaybattles::text||':'||a.totalwin::text||':'||a.totallose::text||':'||a.currenthonor::text||':'||t.todaywin::text||':'||t.todaybattles::text||':'||t.totalwin::text||':'||t.totallose::text||':'||t.currenthonor::text,',' ORDER BY a.entityid)||':'||(SELECT item_uid::text||':'||rune_uid::text||':'||paid_at::text FROM revora_arena_daily_rewards WHERE uid=4294903001 AND milestone='wins9'))
FROM arena a JOIN teamarena t USING(entityid) WHERE a.entityid BETWEEN 4294903001 AND 4294903005");
        var prior=Sql("SELECT fingerprint FROM revora_arena_process_probe");
        if(prior==DBNull.Value)Sql("UPDATE revora_arena_process_probe SET fingerprint=@value","value",fingerprint);
        else Require((string)prior==fingerprint);
        Console.WriteLine("[arena-process] recovered-five-ordinary-fixtures-without-replay");
        Server.CommandsAI("@close");
        throw new InvalidOperationException("Recovered process did not exit normally.");
    }
    static void Spend() {
        nextUid=FirstUid;var winner=Player(Kernel.Maps[1002],true);var loser=Player(Kernel.Maps[1002],true);
        winner.CalculateStatBonus();winner.CalculateHPBonus();loser.CalculateStatBonus();loser.CalculateHPBonus();
        Require(winner.Entity.MaxHitpoints>0 && loser.Entity.MaxHitpoints>0);
        long savedVip=Convert.ToInt64(Sql("SELECT viplevel FROM entities WHERE uid=@uid","uid",(long)FirstUid));
        Require(winner.Entity.VIPLevel==4);
        lock(winner.ItemSyncRoot) {
            Require((bool)Call(Feature("VipState"),"MatchesSavedLevel",winner,savedVip));
            Require(!(bool)Call(Feature("VipState"),"MatchesSavedLevel",winner,savedVip==0?4L:0L));
        }
        const uint pack=3006319;
        Require(HonorShop.Shop.Items[pack]==800);
        long purchases=(long)Sql("SELECT count(*) FROM revora_honor_purchases WHERE uid=@uid","uid",(long)FirstUid);
        if(purchases==0) {
            Require(savedVip==0 && winner.CurrentHonor==500 && winner.HistoryHonor==500);
            // The ninth-win reward alone cannot pay the unchanged catalog price.
            ItemHandler.HandleBuyFromNPC(new ItemUsage(true){UID=HonorShop.UID,dwParam=pack},winner);
            Require(winner.CurrentHonor==500 && winner.Inventory.Count==2);
            Require((long)Sql("SELECT count(*) FROM revora_honor_purchases WHERE uid=@uid","uid",(long)FirstUid)==0);
            for(int wins=10;wins<=20;wins++)EarnRound(winner,loser,wins);
            Call(Feature("ArenaRewardDelivery"),"Tick",winner);
            Call(Feature("ArenaRewardDelivery"),"Tick",loser);
            Require(winner.CurrentHonor==1000 && winner.HistoryHonor==1000 && winner.Inventory.Count==4);
            ItemHandler.HandleBuyFromNPC(new ItemUsage(true){UID=HonorShop.UID,dwParam=pack},winner);
            // A repeated request cannot afford a second item and must preserve the first.
            ItemHandler.HandleBuyFromNPC(new ItemUsage(true){UID=HonorShop.UID,dwParam=pack},winner);
        }
        Call(Feature("ArenaRewardDelivery"),"Tick",winner);
        Call(Feature("ArenaRewardDelivery"),"Tick",loser);
        Require(winner.CurrentHonor==200 && winner.HistoryHonor==1000 && winner.Inventory.Count==5);
        Require(loser.CurrentHonor==500 && loser.Inventory.Count==2);
        Require(!(bool)typeof(Entity).GetField("PersistenceRequiresReload",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(winner.Entity));
        Require((bool)Sql(@"SELECT
(SELECT count(*) FROM revora_arena_result_statistics WHERE uid=@uid AND won)=20
AND (SELECT count(*) FROM revora_arena_daily_rewards WHERE uid=@uid AND paid_at IS NOT NULL AND rune_type=4030101 AND rune_uid IS NOT NULL)=2
AND (SELECT count(*) FROM revora_honor_purchases p JOIN items i ON i.uid=p.item_uid AND i.entityid=p.uid AND i.id=p.item_type WHERE p.uid=@uid AND p.item_type=3006319 AND p.cost=800 AND p.honor_before=1000 AND p.honor_after=200)=1
AND (SELECT currenthonor FROM arena WHERE entityid=@uid)=200
AND (SELECT currenthonor FROM teamarena WHERE entityid=@uid)=200
AND (SELECT count(*) FROM items WHERE entityid=@uid)=5","uid",(long)FirstUid));
        Console.WriteLine("[arena-process] twenty-earned-matches-honor-purchase-persisted");
        Server.CommandsAI("@close");
        throw new InvalidOperationException("Spend process did not exit normally.");
    }
    static void TeamRewards() {
        nextUid=FirstUid+2;var leader=Player(Kernel.Maps[1002],true);var opponent=Player(Kernel.Maps[1002],true);var member=Player(Kernel.Maps[1002],true);
        var players=new[]{leader,opponent,member};
        foreach(var p in players){p.CalculateStatBonus();p.CalculateHPBonus();Require(p.Entity.MaxHitpoints>0);}
        leader.Team=new Revora.Game.ConquerStructures.Team(leader);leader.Team.Add(member);
        opponent.Team=new Revora.Game.ConquerStructures.Team(opponent);
        var instance=BindingFlags.Instance|BindingFlags.NonPublic;
        uint wins=leader.TeamArenaStatistic.TodayWin;
        Require(wins>=1 && wins<=9 && member.TeamArenaStatistic.TodayWin==wins && opponent.TeamArenaStatistic.TodayWin==0);
        for(uint round=wins+1;round<=9;round++) {
            var group=new TeamQualifier.QualifierList.QualifierGroup(leader,opponent);
            var owner=Activator.CreateInstance(Feature("TeamArenaDisconnectRetention"),instance,null,new object[]{4,null},null);
            Call(typeof(TeamQualifier),"ImportMatched",group,owner);
            Require(players.All(p=>ReferenceEquals(p.TeamQualifierGroup,group)));
            group.End(opponent);var limit=DateTime.UtcNow.AddSeconds(10);
            do {
                owner.GetType().GetMethod("Tick",instance).Invoke(owner,new object[]{16});
                if(players.All(p=>p.TeamQualifierGroup==null && typeof(GameState).GetField("ArenaShutdownRetention",instance).GetValue(p)==null))break;
                System.Threading.Thread.Sleep(50);
            }while(DateTime.UtcNow<limit);
            Require(players.All(p=>p.TeamQualifierGroup==null && p.Entity.MapID==1002));
            Require(leader.TeamArenaStatistic.TodayWin==round && member.TeamArenaStatistic.TodayWin==round);
            Console.WriteLine("[arena-process] team-earned-round="+round);
        }
        foreach(var p in players) {
            Call(Feature("ArenaRewardDelivery"),"Tick",p);Call(Feature("TeamArenaDailyRewards"),"Pay",p);
            Require(!(bool)typeof(Entity).GetField("PersistenceRequiresReload",instance).GetValue(p.Entity));
            bool won=p!=opponent;
            Require(p.CurrentHonor==(won?500u:0u) && p.HistoryHonor==(won?500u:0u) && p.Inventory.Count==(won?2:0));
            Require(Convert.ToInt64(Sql("SELECT currenthonor FROM arena WHERE entityid=@uid","uid",(long)p.Entity.UID))==(won?500:0)
                && Convert.ToInt64(Sql("SELECT currenthonor FROM teamarena WHERE entityid=@uid","uid",(long)p.Entity.UID))==(won?500:0));
            Require((long)Sql("SELECT count(*) FROM revora_team_arena_statistics WHERE uid=@uid","uid",(long)p.Entity.UID)==9);
            Require((long)Sql(@"SELECT count(*) FROM revora_team_arena_daily_rewards r
JOIN items i ON i.uid=r.item_uid AND i.entityid=r.uid AND i.id=723700
JOIN items g ON g.uid=r.rune_uid AND g.entityid=r.uid AND g.id=4030101 AND g.bound=1
WHERE r.uid=@uid AND r.milestone='wins9' AND r.honor=500 AND r.paid_at IS NOT NULL","uid",(long)p.Entity.UID)==(won?1:0));
        }
        Console.WriteLine("[arena-process] team-leader-and-member-earned-rewards-persisted");
        Server.CommandsAI("@close");
        throw new InvalidOperationException("Team reward process did not exit normally.");
    }
